package net.civeira.phylax.features.access.consentpurpose.domain.valueholder;

import java.util.Optional;

import lombok.RequiredArgsConstructor;
import net.civeira.phylax.common.value.validation.ConstraintFail;
import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.features.access.consentpurpose.domain.ConsentPurpose;
import net.civeira.phylax.features.access.consentpurpose.domain.valueobject.TitleVO;

@RequiredArgsConstructor
public class TitleValueHolder<T> {

  /**
   * @autogenerated ValueHolderGenerator
   */
  private final T holder;

  /**
   * @autogenerated ValueHolderGenerator
   */
  private Optional<TitleVO> value = Optional.empty();

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public Optional<String> getTitle() {
    return value.map(TitleVO::getTitle);
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public Optional<TitleVO> getTitleValue() {
    return value;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param original
   * @param fails
   * @return
   */
  public TitleVO readTitle(final Optional<ConsentPurpose> original,
      final ConstraintFailList fails) {
    TitleVO result = value.orElse(original.map(ConsentPurpose::getTitleValue).orElse(null));
    if (null == result) {
      fails.add(new ConstraintFail("REQUIRED", "title", null));
    }
    return result;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param title
   * @return
   */
  public T title(TitleVO title) {
    this.value = Optional.of(title);
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param title
   * @return
   */
  public T title(Optional<TitleVO> title) {
    this.value = title;
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param title
   * @return
   */
  public T title(String title) {
    this.value = Optional.of(TitleVO.from(title));
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public T unsetTitle() {
    value = Optional.empty();
    return holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param field
   * @return
   */
  public T unsetTitleIfMatches(final String field) {
    if ("title".equals(field)) {
      value = Optional.empty();
    }
    return holder;
  }
}
